sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_slices;
uniform float amzp_sliceDir;
uniform float amzp_motion;
uniform float amzp_order;
uniform float amzp_wave;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_progress;
uniform float amzp_gap;
uniform float amzp_swingDist;
uniform float amzp_swingAngle;
uniform float amzp_zoomAmt;
uniform float amzp_pivot;
uniform float amzp_altDir;
uniform float amzp_cps;
uniform float amzp_stagger;
uniform float amzp_loopOn;
uniform float amzp_damping;
uniform float amzp_ampVar;
uniform float amzp_seed;
uniform float amzp_shading;
uniform float amzp_edgeSoft;
uniform float amzp_quality;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float hs(float a, float k) { return fract(sin(a * 127.1 + k * 311.7 + amzp_seed * 3.17) * 43758.5453); }
    float waveF(float p) {
        if (int(amzp_wave) == 1) return 4.0 * abs(fract(p - 0.25) - 0.5) - 1.0;
        if (int(amzp_wave) == 2) return clamp(sin(6.2831853 * p) * 5.0, -1.0, 1.0);
        if (int(amzp_wave) == 3) return abs(sin(3.14159265 * p));
        if (int(amzp_wave) == 4) { float q = fract(p); return sin(6.2831853 * q * 3.0) * exp(-4.0 * q); }
        return sin(6.2831853 * p);
    }
    float rankOf(float j, float N) {
        float c = (N - 1.0) * 0.5;
        if (int(amzp_order) == 1) return N - 1.0 - j;
        if (int(amzp_order) == 2) return abs(j - c);
        if (int(amzp_order) == 3) return c - abs(j - c);
        if (int(amzp_order) == 4) return mod(j, 2.0) < 0.5 ? j * 0.5 : ceil(N * 0.5) + floor(j * 0.5);
        if (int(amzp_order) == 5) return floor(hs(j, 7.0) * N);
        return j;
    }
    float swingOf(float j, float N, float T) {
        float t = T * amzp_cps - rankOf(j, N) * amzp_stagger;
        float w;
        if ((amzp_loopOn>0.5)) w = waveF(t);
        else {
            if (t <= 0.0 || t >= 1.0) return 0.0;
            float env = mix(1.0, exp(-3.0 * t) * (1.0 - t), amzp_damping);
            w = (int(amzp_wave) == 4 ? sin(6.2831853 * t * 3.0) * exp(-4.0 * t) : waveF(t)) * env;
        }
        w *= 1.0 + (hs(j, 3.0) - 0.5) * 2.0 * amzp_ampVar;
        if ((amzp_altDir>0.5) && mod(j, 2.0) > 0.5) w = -w;
        return w;
    }
    void amzRender() {
        float2 W = layer;
        bool vert = int(amzp_sliceDir) == 0;
        float Wa = vert ? W.x : W.y;
        float Wb = vert ? W.y : W.x;
        float2 n = amzLayerNorm();
        float a = vert ? n.x * W.x : (1.0 - n.y) * W.y;
        float b = vert ? (1.0 - n.y) * W.y : n.x * W.x;
        float T = amzp_progress * 10.0 + ((amzp_autop>0.5) ? time * amzp_autoSpeed : 0.0);
        float N = max(floor(amzp_slices + 0.5), 1.0);
        float g = clamp(amzp_gap, 0.0, Wa / N * 0.9);
        float sw = (Wa - (N - 1.0) * g) / N;
        float pitch = sw + g;
        float i0 = floor(a / pitch);
        float soft = max(amzp_edgeSoft, 0.001);
        float4 col = float4(0.0);
        float best = -1.0;
        for (int k = -4; k <= 4; k++) {
            if (abs(float(k)) > amzp_quality) continue;
            float j = i0 + float(k);
            if (j < 0.0 || j >= N) continue;
            float w = swingOf(j, N, T);
            float a0 = j * pitch, ac = a0 + sw * 0.5;
            float la = a - ac, lb = b;
            float shade = 1.0;
            if (int(amzp_motion) == 0) lb = b - w * amzp_swingDist;
            else if (int(amzp_motion) == 1) la = la - w * amzp_swingDist;
            else if (int(amzp_motion) == 2) {
                float pb = amzp_pivot * Wb;
                float ang = radians(w * amzp_swingAngle);
                float cs = cos(ang), sn = sin(ang);
                float2 r = float2(la, b - pb);
                r = float2(cs * r.x + sn * r.y, -sn * r.x + cs * r.y);
                la = r.x; lb = r.y + pb;
                shade = 1.0 - amzp_shading * abs(sn) * 0.6;
            } else if (int(amzp_motion) == 3) {
                float ang = radians(w * amzp_swingAngle);
                float cs = cos(ang);
                if (abs(cs) < 0.02) continue;
                la = la / cs;
                shade = 1.0 - amzp_shading * (1.0 - abs(cs));
            } else {
                float z = max(1.0 + w * amzp_zoomAmt, 0.02);
                la = la / z;
                lb = (b - Wb * 0.5) / z + Wb * 0.5;
            }
            float ea = sw * 0.5 - abs(la);
            float eb = min(lb, Wb - lb);
            float cov = clamp(min(ea, eb) / soft + 0.5, 0.0, 1.0);
            if (cov <= 0.0) continue;
            float pri = abs(w) + (k == 0 ? 0.001 : 0.0);
            if (pri <= best) continue;
            best = pri;
            float sa = ac + la, sb = lb;
            float2 uv = vert ? float2(sa / W.x, 1.0 - sb / W.y) : float2(sb / W.x, 1.0 - sa / W.y);
            float4 c = (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) ? float4(0.0) : amzTexture(0, l2s(uv));
            c.rgb *= shade;
            col = c * cov;
        }
        amzOutput = col;
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
